
.header {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  background: var(--c-surface);
  border: none;
  border-bottom: 1px solid var(--c-border);
  cursor: pointer;
  font-family: inherit;
  text-align: left;
}

.left {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.time {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 15px;
  font-weight: 600;
  color: var(--c-text);
}

.weekday {
  font-size: 12px;
  color: var(--c-text-muted);
}

.place-tag {
  display: inline-block;
  width: fit-content;
  background: var(--c-primary-soft);
  color: var(--c-primary);
  border-radius: 6px;
  padding: 2px 10px;
  font-size: 12px;
  font-weight: 500;
}

.right {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--c-text-muted);
  font-size: 12px;
}

.chevron {
  transition: transform 0.25s ease;

  &.open {
    transform: rotate(180deg);
  }
}
