
.people-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.group-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text-muted);
  margin-bottom: 6px;
}

.card-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.empty {
  border: 1px dashed var(--c-border);
  border-radius: 10px;
  padding: 14px;
  text-align: center;
  color: var(--c-text-muted);
  font-size: 12px;
  background: var(--c-surface);
}
