
.person-card {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  padding: 10px 12px;
  animation: card-in 0.3s ease;
}

.person-card.away {
  opacity: 0.65;
}

@keyframes card-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 2px;
}

.age-badge {
  font-size: 11px;
  color: var(--c-primary);
  background: var(--c-primary-soft);
  border-radius: 999px;
  padding: 0 8px;
  font-weight: 500;
}

.name {
  font-weight: 600;
  font-size: 14px;
}

.lamp {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--c-grey);
}

.lamp-已发生 {
  background: var(--c-accent);
  box-shadow: 0 0 6px var(--c-accent);
}

.lamp-常态 {
  background: var(--c-accent-deep);
  box-shadow: 0 0 6px var(--c-accent-deep);
}

.lamp-label {
  font-size: 11px;
  color: var(--c-text-muted);
}

.identity {
  font-size: 12px;
  color: var(--c-text-muted);
  margin-bottom: 8px;
}

.meter {
  height: 6px;
  background: var(--c-primary-soft);
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 6px;
}

.meter-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-warm), var(--c-accent));
  border-radius: 3px;
  transition: width 0.4s ease;
}

.meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.accept {
  font-weight: 600;
  color: var(--c-accent-deep);
}

.accept-label {
  color: var(--c-text-muted);
  flex: 1;
}

.stamp {
  border-radius: 999px;
  padding: 1px 10px;
  font-size: 11px;
  border: 1px solid transparent;
}

.stamp-未接触 {
  color: var(--c-text-muted);
  border-color: var(--c-grey);
}

.stamp-日常 {
  color: var(--c-primary);
  border-color: var(--c-primary);
}

.stamp-暧昧 {
  color: var(--c-warm);
  border-color: var(--c-warm);
}

.stamp-得手 {
  color: #fff;
  background: var(--c-accent);
  border-color: var(--c-accent);
}

.stamp-稳固 {
  color: #fff;
  background: var(--c-steady);
  border-color: var(--c-steady);
}

.detail {
  margin-top: 8px;
  border-top: 1px dashed var(--c-border);
  padding-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(64px, 1fr));
  gap: 4px;
}

.detail-item {
  background: var(--c-bg);
  border-radius: 6px;
  padding: 4px 8px;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.detail-item .k {
  font-size: 10px;
  color: var(--c-text-muted);
}

.detail-item .v {
  font-size: 12px;
  font-weight: 600;
}

.inner {
  background: var(--c-primary-soft);
  border-left: 3px solid var(--c-accent);
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 12px;
  font-style: italic;
}

.hint {
  margin-top: 6px;
  font-size: 11px;
  color: var(--c-text-muted);
  text-align: right;
  opacity: 0.7;
}

.text-block {
  background: var(--c-bg);
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 12px;
}

.text-block .k {
  display: inline-block;
  font-size: 10px;
  color: var(--c-text-muted);
  margin-right: 6px;
}
