
.card {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  background-color: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(61, 61, 61, 0.08);
  font-size: 13px;
  line-height: 1.5;
}

.content-area {
  padding: 10px 12px 14px;
}

.tab-row {
  display: flex;
  gap: 8px;
  margin-bottom: 10px;
}

.tab-btn {
  border: 1px solid var(--c-border);
  background: var(--c-surface);
  color: var(--c-text-muted);
  border-radius: 999px;
  padding: 4px 14px;
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s ease;

  &.active {
    background: var(--c-primary);
    border-color: var(--c-primary);
    color: #fff;
  }
}

.unfold-enter-active,
.unfold-leave-active {
  transition: all 0.25s ease;
}

.unfold-enter-from,
.unfold-leave-to {
  opacity: 0;
  transform: translateY(-6px);
}
